      const texLabel = subscriptLabel ? `\\text{${subscriptLabel[1]}}_{${[...subscriptLabel[2]].map((digit) => "₀₁₂₃₄₅₆₇₈₉".indexOf(digit)).join("")}}` : `\\text{${label}}`;
